    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <!-- Разрешение на отправку уведомлений для Android 13+ -->\n    <uses-permission android:name=\"android.permission.POST_NOTIFICATIONS\" />\n    <!-- Разрешение на точные будильники уведомлений о начале урока -->\n    <uses-permission android:name=\"android.permission.SCHEDULE_EXACT_ALARM\" />\n    <uses-permission android:name=\"android.permission.RECEIVE_BOOT_COMPLETED\" />\n\n    <application\n        android:name=\".OrganizerApp\"\n        android:allowBackup=\"true\"\n        android:icon=\"@android:drawable/ic_menu_my_calendar\"\n        android:label=\"@string/app_name\"\n        android:roundIcon=\"@android:drawable/ic_menu_my_calendar\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@style/Theme.Organizer\">\n\n        <activity\n            android:name=\".MainActivity\"\n            android:exported=\"true\"\n            android:theme=\"@style/Theme.Organizer\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n\n        <!-- Приёмник уведомлений перед началом урока -->\n        <receiver\n            android:name=\".notification.LessonAlarmReceiver\"\n            android:exported=\"false\" />\n\n        <!-- Восстановление уведомлений после перезагрузки устройства -->\n        <receiver\n            android:name=\".notification.BootCompletedReceiver\"\n            android:exported=\"true\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.BOOT_COMPLETED\" />\n            </intent-filter>\n        </receiver>\n\n        <!-- Виджет рабочего стола «Уроки на сегодня» -->\n        <receiver\n            android:name=\".widget.TodayScheduleWidgetReceiver\"\n            android:exported=\"true\"\n            android:label=\"@string/widget_name\">\n            <intent-filter>\n                <action android:name=\"android.appwidget.action.APPWIDGET_UPDATE\" />\n            </intent-filter>\n            <meta-data\n                android:name=\"android.appwidget.provider\"\n                android:resource=\"@xml/today_schedule_widget_info\" />\n        </receiver>\n    </application>\n</manifest>\n"
